head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jlddst05602";
scwin.kosdaqSeg = null;

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — marketType, kosdaqSegment

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.kosdaqSeg = $c.util.getComponent('kosdaqSeg');
        scwin.init_rowCopy();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jlddst05602.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_searchFromDate", fn: function () { return String(String((dma_pageContext.get("searchFromDate") ?? ""))); } },
        { childId: "ipt_searchToDate", fn: function () { return String(String((dma_pageContext.get("searchToDate") ?? ""))); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        $(this).find("input:radio[name=marketType]").click(function() {
                scwin.fnShowKosdaqSeg($(this));
        });
        scwin.fnInitParam();
        // 수동 전환 필요: fnDisplaySearchBtnDates(N) / fnDisplaySearchBtnDatesOnlyPeriod(N) → 작업본 dateSetting 관례로 재설계 (조회 기간 프리셋)
        //   KRX 방향: 재설계 축 — 작업본 정답지 관례 = scwin.dateSetting() + 기간 버튼 핸들러(btn_3mon_onclick 등)가 캘린더 setValue 로 기간을 직접 세움(ULDINF05800 계열 실증). 1:1 대체 함수가 없고 속성 승격도 아님 — 조회 영역 저작 관례로 실현. 요청 명부에서 제외(재설계 분류).
        //   근거: catalog/function-map (이 주석은 고쳐 쓴 뒤 지우십시오)
        /* TODO Stage2: [sdd] 미실현(재설계 분류 #128): fnDisplaySearchBtnDates( "-1 ') */
        if (($c.util.getComponent('ipt_searchFromDate').getValue() == null ? '' : String($c.util.getComponent('ipt_searchFromDate').getValue())) !== '') {
            $c.util.getComponent('cal_fromDate').setValue(($c.util.getComponent("ipt_searchFromDate").getValue() || ''));
        }
        if (($c.util.getComponent('ipt_searchToDate').getValue() == null ? '' : String($c.util.getComponent('ipt_searchToDate').getValue())) !== '') {
            $c.util.getComponent('cal_toDate').setValue(($c.util.getComponent("ipt_searchToDate").getValue() || ''));
        }
        await scwin.fnSearchInit();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst05602.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
// [저작] 기간 프리셋 버튼 — fnDisplaySearchBtnDates 재설계 (btn_cm 텍스트·gcc date 조합)

/**
 * @method
 * @name btn_pd_1w_onclick
 * @description 「1주」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_pd_1w_onclick = function () { try { const to = WebSquare.date.getCurrentServerDate('yyyyMMdd'); const from = $c.date.addDate(to, -7); const f = ($c.util.getComponent('cal_fromDate') || $c.util.getComponent('ipt_fromDate') || $c.util.getComponent('fromDate')); const t = ($c.util.getComponent('cal_toDate') || $c.util.getComponent('ipt_toDate') || $c.util.getComponent('toDate')); if (f && f.setValue) { f.setValue(from); } if (t && t.setValue) { t.setValue(to); } } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jlddst05602.pd_1w' }); } };

/**
 * @method
 * @name btn_pd_1m_onclick
 * @description 「1개월」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_pd_1m_onclick = function () { try { const to = WebSquare.date.getCurrentServerDate('yyyyMMdd'); const from = $c.date.addMonth(to, -1); const f = ($c.util.getComponent('cal_fromDate') || $c.util.getComponent('ipt_fromDate') || $c.util.getComponent('fromDate')); const t = ($c.util.getComponent('cal_toDate') || $c.util.getComponent('ipt_toDate') || $c.util.getComponent('toDate')); if (f && f.setValue) { f.setValue(from); } if (t && t.setValue) { t.setValue(to); } } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jlddst05602.pd_1m' }); } };

/**
 * @method
 * @name btn_pd_3m_onclick
 * @description 「3개월」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_pd_3m_onclick = function () { try { const to = WebSquare.date.getCurrentServerDate('yyyyMMdd'); const from = $c.date.addMonth(to, -3); const f = ($c.util.getComponent('cal_fromDate') || $c.util.getComponent('ipt_fromDate') || $c.util.getComponent('fromDate')); const t = ($c.util.getComponent('cal_toDate') || $c.util.getComponent('ipt_toDate') || $c.util.getComponent('toDate')); if (f && f.setValue) { f.setValue(from); } if (t && t.setValue) { t.setValue(to); } } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jlddst05602.pd_3m' }); } };

/**
 * @method
 * @name btn_pd_6m_onclick
 * @description 「6개월」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_pd_6m_onclick = function () { try { const to = WebSquare.date.getCurrentServerDate('yyyyMMdd'); const from = $c.date.addMonth(to, -6); const f = ($c.util.getComponent('cal_fromDate') || $c.util.getComponent('ipt_fromDate') || $c.util.getComponent('fromDate')); const t = ($c.util.getComponent('cal_toDate') || $c.util.getComponent('ipt_toDate') || $c.util.getComponent('toDate')); if (f && f.setValue) { f.setValue(from); } if (t && t.setValue) { t.setValue(to); } } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jlddst05602.pd_6m' }); } };

/**
 * @method
 * @name btn_pd_1y_onclick
 * @description 「1년」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_pd_1y_onclick = function () { try { const to = WebSquare.date.getCurrentServerDate('yyyyMMdd'); const from = $c.date.addYear(to, -1); const f = ($c.util.getComponent('cal_fromDate') || $c.util.getComponent('ipt_fromDate') || $c.util.getComponent('fromDate')); const t = ($c.util.getComponent('cal_toDate') || $c.util.getComponent('ipt_toDate') || $c.util.getComponent('toDate')); if (f && f.setValue) { f.setValue(from); } if (t && t.setValue) { t.setValue(to); } } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jlddst05602.pd_1y' }); } };

/**
 * @method
 * @name btn_fnFindCorpName2_onclick
 * @description btn_fnFindCorpName2 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_fnFindCorpName2_onclick = function(e){
    try {
        Promise.resolve($c.win.openPopup('/jldfil00033/jldfil00033.xml', { id: "pop_corp_std" }, { method: "loadInitPage" })).then(function (r) { if (!r) return; let a = Array.isArray(r) ? r : [r]; if (a[0] && a[0].__sdd_rec) { const rec = a[0]; const nm = function (s) { return s.replace(/_/g, '').toLowerCase(); }; const ps = (String(scwin.setCorpInfo).match(/\(([^)]*)\)/) || ['', ''])[1].split(',').map(function (s) { return s.trim(); }).filter(Boolean); const nk = {}; for (let k in rec) nk[nm(k)] = rec[k]; a = ps.map(function (p) { return nk[nm(p)]; }); } try { scwin.setCorpInfo.apply(null, a); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'popup-recv' }); } }); return false;

} catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst05602.btn_fnFindCorpName2_onclick' }); }
};

/**
 * @method
 * @name btn_fnSearchCorpName_onclick
 * @description btn_fnSearchCorpName 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_fnSearchCorpName_onclick = async function(e){
    try {
        await scwin.fnSearchCorpName(); return false;

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst05602.btn_fnSearchCorpName_onclick' }); }
};

/**
 * @method
 * @name btn_fnDownload_onclick
 * @description btn_fnDownload 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_fnDownload_onclick = async function(e){
    try {
        await scwin.fnDownload(); return false;

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst05602.btn_fnDownload_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fnDownload
 * @description fn Download 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnDownload = async function () {
    const sbmOptions = {
        id: "tx_fnDownload",
        method: "post",
        action: "/corpgeneral/irschedule.do",
        ref: "dma_fnDownloadReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fnSearch_ajaxsubmit
 * @description fn Search ajaxsubmit 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnSearch_ajaxsubmit = async function () {
    const sbmOptions = {
        id: "tx_fnSearch_ajaxsubmit",
        method: "post",
        action: "/corpgeneral/irschedule.do",
        ref: "dma_fnSearchAjaxsubmitReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fnDetailView_ajaxsubmit
 * @description fn Detail View ajaxsubmit 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnDetailView_ajaxsubmit = async function () {
    const sbmOptions = {
        id: "tx_fnDetailView_ajaxsubmit",
        method: "post",
        action: "/corpgeneral/irschedule.do",
        ref: "dma_fnDetailViewAjaxsubmitReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name keyEvent
 * @description key Event 처리
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.keyEvent = async function (e) {
    if ($c.util.getKeyCode(typeof e !== 'undefined' && e ? e : (typeof event !== 'undefined' ? event : undefined)) === 13 || (typeof e !== 'undefined' && e === 13)) {
        if ($c.util.getKeyCode(event) === 13) {
            if (fnAKCKwdSearchCodeType(eval('document.searchForm.searchName'))) {
                await scwin.fnSearchCorpName();
            }
        }
    }
};

/**
 * @method
 * @name fnShowKosdaqSeg
 * @description fn Show Kosdaq Seg 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.fnShowKosdaqSeg = function (obj) {
    if (obj.val() === "2") {
        scwin.kosdaqSeg.setStyle("display", "");
    } else {
        scwin.kosdaqSeg.setStyle("display", "none");
    }
    $("#searchForm").find("input:radio[name=kosdaqSegment]:input#rSeg").prop("checked", true);
    scwin.fnTooltip();
};

/**
 * @method
 * @name fnSearchInit
 * @description fn Search Init 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearchInit = async function () {
    scwin.fnCloseDetail();
    await scwin.fnSearch();
};

/**
 * @method
 * @name fnSearchCorpName
 * @description fn Search Corp Name 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearchCorpName = async function () {
    $c.util.getComponent("dma_fnDownloadReq").set("repIsuSrtCd", "");
    $c.util.getComponent("dma_fnDownloadReq").set("searchCorpName", $c.util.getComponent('AKCKwd').getValue());
    if (($c.util.getComponent("dma_fnDownloadReq").get("searchCorpName") || '') !== "") {
        Promise.resolve($c.win.openPopup('/jldfil00033/jldfil00033.xml', { id: "pop_corp_std" }, { method: "loadInitPage" })).then(function (r) { if (!r) return; let a = Array.isArray(r) ? r : [r]; if (a[0] && a[0].__sdd_rec) { const rec = a[0]; const nm = function (s) { return s.replace(/_/g, '').toLowerCase(); }; const ps = (String(scwin.setCorpInfo).match(/\(([^)]*)\)/) || ['', ''])[1].split(',').map(function (s) { return s.trim(); }).filter(Boolean); const nk = {}; for (let k in rec) nk[nm(k)] = rec[k]; a = ps.map(function (p) { return nk[nm(p)]; }); } try { scwin.setCorpInfo.apply(null, a); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'popup-recv' }); } });
} else {
    await scwin.fnSearchInit();
}
};

/**
 * @method
 * @name fnSearchCorpNameAllCallBack
 * @description fn Search Corp Name All Call Back 처리
 * @param {*} items items
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearchCorpNameAllCallBack = async function (items) {
    if (items.length === 1) {
        await scwin.fnSearchCorpCode(items[0].repisusrtcd);
    } else {
        if (items.length > 1) {
            Promise.resolve($c.win.openPopup('/jldfil00033/jldfil00033.xml', { id: "pop_corp_std" }, { method: "loadInitPage" })).then(function (r) { if (!r) return; let a = Array.isArray(r) ? r : [r]; if (a[0] && a[0].__sdd_rec) { const rec = a[0]; const nm = function (s) { return s.replace(/_/g, '').toLowerCase(); }; const ps = (String(scwin.setCorpInfo).match(/\(([^)]*)\)/) || ['', ''])[1].split(',').map(function (s) { return s.trim(); }).filter(Boolean); const nk = {}; for (let k in rec) nk[nm(k)] = rec[k]; a = ps.map(function (p) { return nk[nm(p)]; }); } try { scwin.setCorpInfo.apply(null, a); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'popup-recv' }); } });
    } else {
        await scwin.fnSearchCorpCode('');
    }
}
};

/**
 * @method
 * @name fnSearchCorpCode
 * @description fn Search Corp Code 처리
 * @param {String} ipt_repIsuSrtCd ipt_repIsuSrtCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearchCorpCode = async function (ipt_repIsuSrtCd) {
    if (ipt_repIsuSrtCd === "") {
        $c.util.getComponent("dma_fnDownloadReq").set("repIsuSrtCd", "");
        const val = ($c.util.getComponent("dma_fnDownloadReq").get("searchCodeType") || '');
        if (val === "number") {
            await $c.win.alert("조회한 종목코드가 존재하지 않습니다.");
        } else {
            await $c.win.alert("조회한 회사명이 존재하지 않습니다.");
        }
    } else {
        $c.util.getComponent("dma_fnDownloadReq").set("repIsuSrtCd", ipt_repIsuSrtCd);
        await scwin.fnSearchInit();
    }
};

/**
 * @method
 * @name fnInitParam
 * @description fn Init Param 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnInitParam = function () {
    const marketType = (String(((dma_pageContext.get("marketType") ?? "")) == null ? '' : ((dma_pageContext.get("marketType") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("marketType") ?? "")) == null ? '' : ((dma_pageContext.get("marketType") ?? ""))));
    const kosdaqSegment = (String(((dma_pageContext.get("kosdaqSegment") ?? "")) == null ? '' : ((dma_pageContext.get("kosdaqSegment") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("kosdaqSegment") ?? "")) == null ? '' : ((dma_pageContext.get("kosdaqSegment") ?? ""))));
    if (marketType !== "") {
        $("#searchForm").find("input:radio[name=marketType]").removeAttr("checked");
        if (marketType === "1") {
            $("#searchForm").find("input:radio[id=rWertpapier]").attr("checked", "checked");
        } else {
            if (marketType === "2") {
                $("#searchForm").find("input:radio[id=rKosdaq]").attr("checked", "checked");
                if (kosdaqSegment) {
                    if (kosdaqSegment === "1") {
                        $("#searchForm").find("input:radio[id=rGlobal]").attr("checked", "checked");
                    } else {
                        if (kosdaqSegment === "2") {
                            $("#searchForm").find("input:radio[id=ipt_rGeneral]").attr("checked", "checked");
                        } else {
                            $("#searchForm").find("input:radio[id=rSeg]").attr("checked", "checked");
                        }
                    }
                } else {
                    $("#searchForm").find("input:radio[id=rSeg]").attr("checked", "checked");
                }
                scwin.kosdaqSeg.setStyle("display", "");
            } else {
                if (marketType === "6") {
                    $("#searchForm").find("input:radio[id=rKonex]").attr("checked", "checked");
                } else {
                    $("#searchForm").find("input:radio[id=rAll]").attr("checked", "checked");
                }
            }
        }
    }
};

/**
 * @method
 * @name fnSearch
 * @description fn Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearch = async function () {
    const varTabIndex = $("#searchForm > #tabIndex").val();
    const fromDate = $c.util.getComponent('cal_fromDate').getValue();
    const toDate = $c.util.getComponent('cal_toDate').getValue();
    if (!$c.date.isDate(fromDate)) {
        await $c.win.alert("시작일자 형식이 틀립니다");
        return;
    }
    if (!$c.date.isDate(toDate)) {
        await $c.win.alert("종료일자 형식이 틀립니다");
        return;
    }
    if (!($c.date.diffDate(fromDate, toDate) < 0 ? (await $c.win.alert('조회 기간이 올바르지 않습니다. 시작일자가 종료일자보다 늦습니다.'), false) : true)) {
        return;
    }
    $c.util.getComponent("dma_fnDownloadReq").set("method", "searchIRMaterialsSub");
    $c.util.getComponent("dma_fnDownloadReq").set("forward", "searchirmaterials_sub");
    if ($(document).find("select[id=ipt_currentPageSize]").val() != null) {
        $c.util.getComponent("dma_fnDownloadReq").set("currentPageSize", $(document).find("select[id=ipt_currentPageSize]").val());
    }
    await scwin.tx_fnSearch_ajaxsubmit();
};

/**
 * @method
 * @name fnSearchCallBack
 * @description fn Search Call Back 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.fnSearchCallBack = function (data) {
    $("#mainContents").empty().append(data);
    $("tr:odd").addClass("active");
};

/**
 * @method
 * @name fnSearch1
 * @description fn Search1 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearch1 = async function () {
    $c.util.getComponent("dma_fnDownloadReq").set("pageIndex", "1");
    $c.util.getComponent("dma_fnDownloadReq").set("currentPageSize", $(document).find("select[id=ipt_currentPageSize]").val());
    await scwin.fnSearch();
};

/**
 * @method
 * @name fnDownload
 * @description fn Download 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnDownload = async function () {
    if (!$c.date.isDate($c.util.getComponent('cal_fromDate').getValue())) {
        await $c.win.alert("시작일자 형식이 틀립니다");
        return;
    }
    if (!$c.date.isDate($c.util.getComponent('cal_toDate').getValue())) {
        await $c.win.alert("종료일자 형식이 틀립니다");
        return;
    }
    if (!($c.date.diffDate($c.util.getComponent('cal_fromDate').getValue(), $c.util.getComponent('cal_toDate').getValue()) < 0 ? (await $c.win.alert('조회 기간이 올바르지 않습니다. 시작일자가 종료일자보다 늦습니다.'), false) : true)) {
        return;
    }
    $c.util.getComponent("dma_fnDownloadReq").set("currentPageSize", "3000");
    $c.util.getComponent("dma_fnDownloadReq").set("pageIndex", "1");
    $c.util.getComponent("dma_fnDownloadReq").set("method", "searchIRMaterialsSub");
    $c.util.getComponent("dma_fnDownloadReq").set("forward", "searchirmaterials_down");
    await scwin.tx_fnDownload();
};

/**
 * @method
 * @name fnDetailView
 * @description fn Detail View 처리
 * @param {*} ipt_irSeq ipt_irSeq
 * @param {*} ipt_resoroomType ipt_resoroomType
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnDetailView = async function (ipt_irSeq, ipt_resoroomType) {
    $c.util.getComponent("dma_fnDownloadReq").set("irSeq", ipt_irSeq);
    $c.util.getComponent("dma_fnDownloadReq").set("resoroomType", ipt_resoroomType);
    $c.util.getComponent("dma_fnDownloadReq").set("method", "searchIRMaterialsDetail");
    await scwin.tx_fnDetailView_ajaxsubmit();
};

/**
 * @method
 * @name fnSearchDetailCallBack
 * @description fn Search Detail Call Back 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.fnSearchDetailCallBack = function (data) {
    $("#detailContents").empty().append(data);
    $c.util.getComponent("detailContents").setStyle("display", "");
};

/**
 * @method
 * @name fnCloseDetail
 * @description fn Close Detail 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnCloseDetail = function () {
    $("#detailContents").empty();
    $c.util.getComponent("detailContents").setStyle("display", "none");
};

/**
 * @method
 * @name fnFileDown
 * @description fn File Down 처리
 * @param {*} ipt_method ipt_method
 * @param {String} ipt_resoroomId ipt_resoroomId
 * @param {*} ipt_attachSeq ipt_attachSeq
 * @param {String} ipt_attachFileNm ipt_attachFileNm
 * @param {*} ipt_resoroomType ipt_resoroomType
 * @param {*} ipt_attachType ipt_attachType
 * @returns {void}
 * @hidden N
 */
scwin.fnFileDown = function (ipt_method, ipt_resoroomId, ipt_attachSeq, ipt_attachFileNm, ipt_resoroomType, ipt_attachType) {
    if ("" === ipt_method) {
        ipt_method = "searchIRMaterials";
    }
    $c.util.getComponent("dma_fnDownloadReq").set("method", ipt_method);
    $c.util.getComponent("dma_fnDownloadReq").set("resoroomId", ipt_resoroomId);
    $c.util.getComponent("dma_fnDownloadReq").set("attachSeq", ipt_attachSeq);
    $c.util.getComponent("dma_fnDownloadReq").set("attachFileNm", ipt_attachFileNm);
    $c.util.getComponent("dma_fnDownloadReq").set("attachType", ipt_attachType);
    $("#fileDownForm").submit();
};

