/**
 * @method
 * @name fnTooltip
 * @description fn Tooltip 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnTooltip = function () {
    $(".tttt").hover(function(e) {
            const varTop = $(this).position().top;
            const varLeft = $(this).position().left;
            $("#qmark").css("top", varTop - 10);
            $("#qmark").css("left", varLeft + 15);
            document.qmark.setStyle("display", "");
        }, function(e) {
            document.qmark.setStyle("display", "none");
    });
};
